INSERT INTO rapport (titre, date_rapport, details_analyse, ref_rapport) VALUES
    ('Rapport qualité air - Auvergne-Rhône-Alpes - janvier 2017', '2017-01-01', 'Analyse mensuelle de la qualité de l''air en région Auvergne-Rhône-Alpes pour janvier 2017. Ce rapport compile les concentrations moyennes relevées par les capteurs de la région pour les 8 gaz surveillés : CO2, CH4, N2O, NO2, O3, CO, NH3, HFC.', 'RAP-0000001'),
