-- 8. INSERTION DES CAPTEURS (60 capteurs)


/* INSERTION DES RELEVÉS 
- Nous allons générer des relevés sur plusieurs mois (janvier 2017 à Décembre 2024)
- Chaque capteur a 1 relevé
- La génération des relevés se fait de façon automatique pour tous les capteurs
- Concentration : entre 0.1 et 500  */

SET @ref := 0;

SELECT 
    CONCAT('REL-', LPAD(@ref := @ref + 1, 7, '0')) AS ref_releves,
    DATE_FORMAT(DATE_ADD('2017-01-01', INTERVAL m MONTH), '%Y-%m-01') AS date_releves,
    ROUND(RAND() * (500 - 0.1) + 0.1, 2) AS concentration_gaz,
    c.id_capteur
FROM capteur c
CROSS JOIN (
    SELECT 0 AS m UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5
    UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9 UNION SELECT 10 UNION SELECT 11
    UNION SELECT 12 UNION SELECT 13 UNION SELECT 14 UNION SELECT 15 UNION SELECT 16 UNION SELECT 17
    UNION SELECT 18 UNION SELECT 19 UNION SELECT 20 UNION SELECT 21 UNION SELECT 22 UNION SELECT 23
    UNION SELECT 24 UNION SELECT 25 UNION SELECT 26 UNION SELECT 27 UNION SELECT 28 UNION SELECT 29
    UNION SELECT 30 UNION SELECT 31 UNION SELECT 32 UNION SELECT 33 UNION SELECT 34 UNION SELECT 35
    UNION SELECT 36 UNION SELECT 37 UNION SELECT 38 UNION SELECT 39 UNION SELECT 40 UNION SELECT 41
    UNION SELECT 42 UNION SELECT 43 UNION SELECT 44 UNION SELECT 45 UNION SELECT 46 UNION SELECT 47
    UNION SELECT 48 UNION SELECT 49 UNION SELECT 50 UNION SELECT 51 UNION SELECT 52 UNION SELECT 53
    UNION SELECT 54 UNION SELECT 55 UNION SELECT 56 UNION SELECT 57 UNION SELECT 58 UNION SELECT 59
    UNION SELECT 60 UNION SELECT 61 UNION SELECT 62 UNION SELECT 63 UNION SELECT 64 UNION SELECT 65
    UNION SELECT 66 UNION SELECT 67 UNION SELECT 68 UNION SELECT 69 UNION SELECT 70 UNION SELECT 71
    UNION SELECT 72 UNION SELECT 73 UNION SELECT 74 UNION SELECT 75 UNION SELECT 76 UNION SELECT 77
    UNION SELECT 78 UNION SELECT 79 UNION SELECT 80 UNION SELECT 81 UNION SELECT 82 UNION SELECT 83
    UNION SELECT 84 UNION SELECT 85 UNION SELECT 86 UNION SELECT 87 UNION SELECT 88 UNION SELECT 89
    UNION SELECT 90 UNION SELECT 91 UNION SELECT 92 UNION SELECT 93 UNION SELECT 94 UNION SELECT 95
) AS months
ORDER BY c.id_capteur, m;

/*
-- table rapport  -- INSERTION ASSISTEE PAR COPILOT DES RAPPORTS
-- 1 rapport par région et par mois (jan 2017 - déc 2024)
-- Chaque rapport couvre les 8 gaz surveillés de la région pour le mois
-- Total : 13 régions × 96 mois = 1 248 rapports
*/


-- INSERTION TABLE ECRIRE (Agents administratifs écrivant les rapports)
SELECT 
    ELT(((rap.id_rapport - 1) % 63) + 1,
        9, 8, 2, 6, 5, 17, 16, 12, 15, 26, 23, 28, 24, 29, 33, 35, 31, 32, 36, 46,
        49, 41, 43, 45, 51, 53, 57, 55, 52, 65, 64, 63, 69, 62, 79, 75, 72, 74, 78,
        85, 90, 89, 81, 88, 96, 95, 93, 92, 97, 101, 106, 109, 104, 103, 113, 115,
        119, 112, 118, 121, 126, 122, 124
    ) AS id_personnel,
    rap.id_rapport
FROM rapport rap
ORDER BY rap.id_rapport;

--  INSERTION TABLE PEUT_SE_TROUVER (Relevés liés aux rapports)
SELECT DISTINCT
    rel.id_releves,
    rap.id_rapport
FROM rapport rap
JOIN releves rel ON rel.date_releves = rap.date_rapport
JOIN capteur c   ON c.id_capteur     = rel.id_capteur
JOIN adresse_postale ap ON ap.id_adresse = c.id_adresse
JOIN region rg   ON rg.id_region     = ap.id_region
WHERE rap.titre LIKE CONCAT('Rapport qualité air - ', rg.nom_region, ' -%');

